298	/* CVITEK cv182xa */
299	static int cv182xa_config(struct phy_device *phydev)
300	{
301		//phy_reset(phydev);
302	
303		cv182xa_ephy_init();/* config cvitek cv182xa eth internal phy on ASIC board */
304	
305		genphy_config(phydev);
306	
307	#if defined(CVI_ETH_PHY_LOOPBACK)
308		cv182xa_set_phy_loopback(phydev, LOOPBACK_PCS2MAC);
309	#endif
310	
311		return 0;
312	}
313	
314	static int cv182xa_parse_status(struct phy_device *phydev)
315	{
316		int mii_reg;
317	
318		mii_reg = phy_read(phydev, MDIO_DEVAD_NONE, MII_BMSR);
319	
320		if (mii_reg & (BMSR_100FULL | BMSR_100HALF))
321			phydev->speed = SPEED_100;
322		else
323			phydev->speed = SPEED_10;
324	
325		if (mii_reg & (BMSR_10FULL | BMSR_100FULL))
326			phydev->duplex = DUPLEX_FULL;
327		else
328			phydev->duplex = DUPLEX_HALF;
329	
330		return 0;
331	}
332	
333	static int cv182xa_startup(struct phy_device *phydev)
334	{
335		int ret;
336	
337		/* Read the Status (2x to make sure link is right) */
338		ret = genphy_update_link(phydev);
339		if (ret)
340			return ret;
341	
342		return cv182xa_parse_status(phydev);
343	}
344	
345	/* Support for cv182xa PHYs */
346	static struct phy_driver cv182xa_driver = {
347		.name = "CVITEK CV182XA",
348		.uid = 0x00435649,
349		.mask = 0xffffffff,
350		.features = PHY_BASIC_FEATURES,
351		.config = &cv182xa_config,
352		.startup = &cv182xa_startup,
353		.shutdown = &genphy_shutdown,
354	};
355	
356	int phy_cvitek_init(void)
357	{
358		phy_register(&cv182xa_driver);
359	
360		return 0;
361	}
