890		free(priv->phydev);
891		mdio_unregister(priv->bus);
892		mdio_free(priv->bus);
893	
894	#ifdef CONFIG_CLK
895		return clk_release_all(priv->clocks, priv->clock_count);
896	#else
897		return 0;
898	#endif
899	}
