924		pdata->phy_interface = -1;
925		phy_mode = dev_read_string(dev, "phy-mode");
926		if (phy_mode)
927			pdata->phy_interface = phy_get_interface_by_name(phy_mode);
928		if (pdata->phy_interface == -1) {
929			debug("%s: Invalid PHY interface '%s'\n", __func__, phy_mode);
930			return -EINVAL;
931		}
932	
933		pdata->max_speed = dev_read_u32_default(dev, "max-speed", 0);
934	
935	#if CONFIG_IS_ENABLED(DM_GPIO)
936		if (dev_read_bool(dev, "snps,reset-active-low"))
937			reset_flags |= GPIOD_ACTIVE_LOW;
938	
939		ret = gpio_request_by_name(dev, "snps,reset-gpio", 0,
940			&priv->reset_gpio, reset_flags);
941		if (ret == 0) {
942			ret = dev_read_u32_array(dev, "snps,reset-delays-us",
943						 dw_pdata->reset_delays, 3);
944		} else if (ret == -ENOENT) {
945			ret = 0;
946		}
947	#endif
948	
949		return ret;
950	}
